  1→<!--
  2→  AC: @ui-session-history ac-1 — Session list with ID, agent type, task ref, status, duration, age.
  3→  AC: @ui-session-history ac-2 — Click navigates to /sessions/:id.
  4→-->
  5→<script lang="ts">
  6→	import { onMount } from 'svelte';
  7→	import { base } from '$app/paths';
  8→	import type { SessionSummary } from '$lib/api';
  9→	import { fetchSessions } from '$lib/api';
 10→	import { isStaticMode } from '$lib/stores/mode.svelte';
 11→	import { formatElapsed, formatAge } from '$lib/components/session/session-utils';
 12→	import { Badge } from '$lib/components/ui/badge';
 13→	import Activity from '@lucide/svelte/icons/activity';
 14→
 15→	let sessions = $state<SessionSummary[]>([]);
 16→	let loading = $state(true);
 17→	let error = $state('');
 18→
 19→	async function loadSessions() {
