   345→export function searchStatic(query: string): SearchResponse {
   346→	const snapshot = getSnapshot();
   347→	if (!snapshot) {
   348→		return { results: [], total: 0, showing: 0 };
   349→	}
   350→
   351→	const lowerQuery = query.toLowerCase();
   352→	const results: SearchResult[] = [];
   353→
   354→	// Search tasks
   355→	for (const task of snapshot.tasks) {
   356→		if (
   357→			task.title.toLowerCase().includes(lowerQuery) ||
   358→			task.slugs.some((s) => s.includes(lowerQuery))
   359→		) {
   360→			results.push({
   361→				type: 'task',
   362→				ulid: task._ulid,
   363→				title: task.title,
   364→				matchedFields: ['title']
   365→			});
   366→		}
   367→	}
   368→
   369→	// Search items
   370→	for (const item of snapshot.items) {
   371→		if (
   372→			item.title.toLowerCase().includes(lowerQuery) ||
   373→			item.slugs.some((s) => s.includes(lowerQuery))
   374→		) {
   375→			results.push({
   376→				type: 'item',
   377→				ulid: item._ulid,
   378→				title: item.title,
   379→				matchedFields: ['title']
   380→			});
   381→		}
   382→	}
   383→
   384→	// Search inbox
   385→	for (const inbox of snapshot.inbox) {
   386→		if (inbox.text.toLowerCase().includes(lowerQuery)) {
   387→			results.push({
   388→				type: 'inbox',
   389→				ulid: inbox._ulid,
   390→				title: inbox.text.slice(0, 50),
   391→				matchedFields: ['text']
   392→			});
   393→		}
   394→	}
   395→
   396→	return {
   397→		results: results.slice(0, 20),
   398→		total: results.length,
   399→		showing: Math.min(results.length, 20)
   400→	};
   401→}
   402→
   403→/**
   404→ * Fetch triage records from static snapshot
   405→ * AC: @interactive-triage-ui ac-8
   406→ *
   407→ * Triage records are not included in static snapshots, so this always
   408→ * returns an empty list. Params are accepted for API compatibility.
   409→ */
   410→export function fetchTriageRecordsStatic(params?: {
   411→	status?: string;
   412→	action?: string;
   413→	limit?: number;
   414→	offset?: number;
   415→}): PaginatedResponse<never> {
   416→	return { items: [], total: 0, offset: params?.offset ?? 0, limit: params?.limit ?? 50 };
   417→}
   418→
   419→// ============================================================
   420→// Write Operations (throw ReadOnlyModeError)
   421→// ============================================================
   422→
   423→/**
   424→ * Start task - not available in static mode
   425→ * AC: @gh-pages-export ac-16, ac-18
   426→ */
   427→export function startTaskStatic(_ref: string): never {
   428→	throw new ReadOnlyModeError('start task');
   429→}
   430→
   431→/**
   432→ * Add task note - not available in static mode
   433→ * AC: @gh-pages-export ac-18
   434→ */
   435→export function addTaskNoteStatic(_ref: string, _content: string): never {
   436→	throw new ReadOnlyModeError('add note');
   437→}
