634→/**
635→ * Start or stop the dispatch engine
636→ * AC: @ui-agent-dispatch ac-2
637→ */
638→export async function controlDispatch(action: 'start' | 'stop'): Promise<{ dispatch_enabled: boolean }> {
639→	assertWritable('control dispatch');
640→
641→	const response = await fetch(`${API_BASE}/api/agent/dispatch`, {
642→		method: 'POST',
643→		headers: {
644→			'Content-Type': 'application/json',
645→			...getProjectHeaders()
646→		},
647→		body: JSON.stringify({ action })
648→	});
649→	if (!response.ok) {
650→		await handleResponseError(response);
651→	}
652→	return response.json();
653→}
654→
655→/**
656→ * Execute a triage action
657→ * AC: @interactive-triage-ui ac-3
658→ */
659→export async function actOnTriageRecord(
660→	ref: string
661→): Promise<{ success: boolean; record: TriageRecord }> {
662→	assertWritable('execute triage action');
663→
664→	const response = await fetch(`${API_BASE}/api/triage/${ref}/act`, {
665→		method: 'POST',
666→		headers: getProjectHeaders()
667→	});
668→	if (!response.ok) {
669→		await handleResponseError(response);
670→	}
671→
672→	return response.json();
673→}
674→
675→// ============================================================
676→// Session API Functions
677→// AC: @ui-session-stream ac-1, ac-2, ac-4
678→// ============================================================
679→
680→/**
681→ * Session summary from the daemon API.
682→ */
683→export interface SessionSummary {
684→	id: string;
685→	status: 'active' | 'completed' | 'abandoned' | 'timed_out' | 'failed';
686→	agent_type: string;
687→	session_type: 'loop' | 'invocation';
688→	/** Task ID being worked on (if any). AC: @ui-session-history ac-1 */
689→	task_id?: string;
690→	started_at: string;
691→	ended_at?: string;
692→	duration_ms: number;
693→	event_count: number;
694→	iteration_count: number;
695→	tasks_completed: number;
696→}
697→
698→/**
699→ * Spec context with acceptance criteria checklist.
700→ * AC: @ui-session-stream ac-4
701→ */
702→export interface SessionSpecContext {
703→	spec_ref: string;
704→	title: string;
705→	acceptance_criteria: Array<{ id: string; description: string }>;
706→}
707→
708→/**
709→ * Session budget info.
710→ * AC: @ui-session-stream ac-4
711→ */
712→export interface SessionBudget {
713→	max_per_cycle: number;
714→	started_this_cycle: number;
715→}
716→
717→/**
718→ * Session detail with additional metadata.
719→ * AC: @ui-session-stream ac-4
720→ */
721→export interface SessionDetail extends SessionSummary {
722→	task_id?: string;
723→	agent_id?: string;
724→	trigger?: string;
725→	spec_context?: SessionSpecContext | null;
726→	budget?: SessionBudget | null;
727→}
728→
729→/**
730→ * A single event from events.jsonl.
731→ */
732→export interface SessionEvent {
733→	ts: number;
734→	seq: number;
735→	type: string;
736→	session_id: string;
737→	trace_id?: string;
738→	data: unknown;
739→}
740→
741→/**
742→ * Fetch all sessions with summaries.
743→ * AC: @ui-session-stream ac-1
744→ */
745→export async function fetchSessions(): Promise<{ items: SessionSummary[]; total: number }> {
746→	if (isStaticMode()) {
747→		return { items: [], total: 0 };
748→	}
749→
750→	const response = await fetch(`${API_BASE}/api/sessions`, {
751→		headers: getProjectHeaders()
752→	});
753→	if (!response.ok) {
754→		await handleResponseError(response);
755→	}
756→
757→	return response.json();
758→}
759→
760→/**
761→ * Fetch a single session by ID.
762→ * AC: @ui-session-stream ac-4
763→ */
764→export async function fetchSession(id: string): Promise<SessionDetail> {
765→	if (isStaticMode()) {
766→		throw new Error('Session data not available in static mode');
767→	}
768→
769→	const response = await fetch(`${API_BASE}/api/sessions/${id}`, {
770→		headers: getProjectHeaders()
771→	});
772→	if (!response.ok) {
773→		await handleResponseError(response);
774→	}
775→
776→	return response.json();
777→}
778→
779→/**
780→ * Fetch session events (optionally incremental via since_seq).
781→ * AC: @ui-session-stream ac-1, ac-2
782→ */
783→export async function fetchSessionEvents(
784→	id: string,
785→	sinceSeq?: number
786→): Promise<{ events: SessionEvent[]; total: number }> {
787→	if (isStaticMode()) {
788→		return { events: [], total: 0 };
789→	}
790→
791→	const url = new URL(`${API_BASE}/api/sessions/${id}/events`);
792→	if (sinceSeq !== undefined) {
793→		url.searchParams.set('since_seq', String(sinceSeq));
794→	}
795→
796→	const response = await fetch(url.toString(), {
797→		headers: getProjectHeaders()
798→	});
799→	if (!response.ok) {
800→		await handleResponseError(response);
801→	}
802→
803→	return response.json();
804→}
