// ============================================================
// Agent & Dispatch API Functions
// AC: @ui-agent-dispatch ac-1, ac-2, ac-3
// ============================================================

/**
 * Agent definition from GET /api/meta/agents
 */
export interface AgentDefinition {
	_ulid: string;
	id: string;
	name: string;
	description?: string;
	adapter?: string;
	dispatch: Array<{
		on: string;
		filter?: {
			automation?: string;
			tags?: string[];
			priority?: number;
		};
	}>;
	capabilities: string[];
	tools: string[];
	skills: string[];
